import pty, os, select, time, signal, re, fcntl, termios, struct
modes=['2','3','4','w']
ansi=re.compile(r'\x1b\[[0-?]*[ -/]*[@-~]|\x1b\][^\x07]*(?:\x07|\x1b\\)|\x1b[()][A-Za-z0-9]|\x1b[=>]|\x1b\[\?[0-9;]*[hl]')
for mode in modes:
    cmd=['./executable','--nokb','--n',mode,'--top','1','--combi','1','--rep','1','--wpm','1','--acc','0']
    pid, fd=pty.fork()
    if pid==0:
        os.environ['TERM']='xterm-256color'; os.execv(cmd[0],cmd)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', 24, 80,0,0))
    out=b''; st=time.time()
    while time.time()-st<0.25:
        r,_,_=select.select([fd],[],[],0.02)
        if r:
            try: out+=os.read(fd,4096)
            except OSError: break
    os.write(fd,b'\x1b')
    time.sleep(.05)
    try:
        while select.select([fd],[],[],0)[0]: out+=os.read(fd,4096)
    except OSError: pass
    try: os.waitpid(pid,0)
    except: pass
    s=out.decode('utf-8','replace')
    clean=ansi.sub('',s)
    print('MODE',mode)
    # print lines containing likely lesson output or clean repr tail
    print(repr(clean[:1000]))
